	cmd.SetOut(&bytes.Buffer{})
	cmd.SetErr(&bytes.Buffer{})
	cmd.SetArgs([]string{"--summarize-provider", "opencode"})

	err := cmd.Execute()
	if err == nil {
		t.Fatal("expected error for unsupported summary provider")
	}
}

