 if err != nil {return "",fmt.Errorf("encoding OpenCode generation configuration: %w",err)}
 return string(raw),nil
}

// OpenCode emits completed text as JSON events and can emit an API error even
// when the process exits successfully. Never return partial text after an error.
func parseOpenCodeGeneration(raw string) (string,error) {
 decoder := json.NewDecoder(strings.NewReader(raw))
 var parts []string
 for {
  var event struct {
   Type string `json:"type"`
   Part struct {Text string `json:"text"`} `json:"part"`
   Error struct {
    Name string `json:"name"`
    Data struct {Message string `json:"message"`} `json:"data"`
   } `json:"error"`
  }
  err := decoder.Decode(&event)
  if errors.Is(err,io.EOF) {break}
  if err != nil {return "",fmt.Errorf("decoding OpenCode output: %w",err)}
  switch event.Type {
