   if detail == "" {detail = event.Error.Name}
   if detail == "" {detail = "unknown error"}
   return "",fmt.Errorf("OpenCode: %s",detail)
  }
 }
 text := strings.TrimSpace(strings.Join(parts,"\n"))
 if text == "" {return "",errors.New("OpenCode returned no text")}
 return text,nil
}
