package cli

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// runnersDir is the canonical location of the trail runner configs for a repo.
func runnersDir(repoRoot string) string {
	return filepath.Join(repoRoot, paths.EntireDir, "runners")
}

// tuneRunner is one .entire/runners/*.json file loaded for tuning. Raw holds
// the verbatim file bytes (used for surgical template replacement); Template is
// the current prompt.template extracted for display in the prompt.
type tuneRunner struct {
	ID       string
	Path     string
	Raw      []byte
	Template string
}

// loadTuneRunners reads the runner configs under <repoRoot>/.entire/runners.
// When filter is non-empty it keeps only the runner whose id matches (with or
// without the "trail-" prefix). Returns an error when the directory is missing
// or the filter matches nothing.
func loadTuneRunners(repoRoot, filter string) ([]tuneRunner, error) {
	dir := runnersDir(repoRoot)
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("reading %s: %w", dir, err)
	}

	var runners []tuneRunner
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
			continue
		}
		path := filepath.Join(dir, e.Name())
		raw, err := os.ReadFile(path) //nolint:gosec // path is derived from repo root + dir listing
		if err != nil {
			return nil, fmt.Errorf("reading %s: %w", path, err)
		}
		var doc struct {
			ID     string `json:"id"`
			Prompt struct {
				Template string `json:"template"`
			} `json:"prompt"`
		}
		if err := json.Unmarshal(raw, &doc); err != nil {
			return nil, fmt.Errorf("parsing %s: %w", path, err)
		}
		if doc.ID == "" {
			doc.ID = strings.TrimSuffix(e.Name(), ".json")
		}
		runners = append(runners, tuneRunner{
			ID:       doc.ID,
			Path:     path,
			Raw:      raw,
			Template: doc.Prompt.Template,
		})
	}

	if filter != "" {
		want := normalizeRunnerID(filter)
		filtered := runners[:0]
		for _, r := range runners {
			if normalizeRunnerID(r.ID) == want {
				filtered = append(filtered, r)
			}
		}
		runners = filtered
		if len(runners) == 0 {
			return nil, fmt.Errorf("no runner matching %q under %s", filter, dir)
		}
	}

	if len(runners) == 0 {
		return nil, fmt.Errorf("no runner configs found under %s", dir)
	}
	sort.Slice(runners, func(i, j int) bool { return runners[i].ID < runners[j].ID })
	return runners, nil
}

func normalizeRunnerID(id string) string {
	return strings.TrimPrefix(strings.TrimSpace(id), "trail-")
}

package summarize

import (
	"context"
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
)

// TextGeneratorAdapter uses an agent.TextGenerator with Entire's shared
// summary prompt and response parser. Detects streaming-capable agents
// (StreamingTextGenerator) and prefers them when present so the explain
// progress UI receives live phase events.
type TextGeneratorAdapter struct {
	TextGenerator agent.TextGenerator
	Model         string

	// progress is forwarded by GenerateFromTranscript when the caller passes
	// a non-nil ProgressFn. Used only by streaming-capable underlying
	// generators; non-streaming agents leave this unused. Unexported so
	// external packages cannot bypass GenerateFromTranscript and set it
	// directly.
	progress agent.ProgressFn
}

// Generate creates a summary using the shared prompt, then delegates raw text
// generation to the configured agent provider. Prefers
// agent.StreamingTextGenerator when the underlying agent supports it (so
// progress events reach the explain UI); falls through to GenerateText
// otherwise.
func (g *TextGeneratorAdapter) Generate(ctx context.Context, input Input) (*checkpoint.Summary, error) {
	if g.TextGenerator == nil {
		return nil, errors.New("text generator not configured")
	}
	transcriptText := FormatCondensedTranscript(input)
	prompt := buildSummarizationPrompt(transcriptText)

	// Prefer streaming when the underlying agent supports it. TextGenerator
	// embeds Agent, so AsStreamingTextGenerator accepts it directly.
	if streamer, ok := agent.AsStreamingTextGenerator(g.TextGenerator); ok {
		result, err := streamer.GenerateTextStreaming(ctx, prompt, g.Model, g.progress)
		if err != nil {
			return nil, err //nolint:wrapcheck // preserve *agent.TextGenerationError / *claudecode.ClaudeError for errors.As
		}
		return parseSummaryText(result)
	}

	result, err := g.TextGenerator.GenerateText(ctx, prompt, g.Model)
	if err != nil {
		return nil, fmt.Errorf("provider text generation failed: %w", err)
	}

	return parseSummaryText(result)
}
package cli

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/interactive"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/spf13/cobra"
)

const runnerSetupLimitErrorMessage = "limit must be greater than 0"

type runnerSetupOptions struct {
	runner       string // optional: limit to one runner (id, with or without "trail-")
	run          bool   // headless apply vs. print prompt
	assumeYes    bool   // skip the create-defaults confirmation
	debugDir     string // if set, dump prompt.txt (+ response.txt on --run) here
	sources      []string
	limit        int
	insecureHTTP bool
}

func newRunnerSetupCmd() *cobra.Command {
	var (
		run       bool
		assumeYes bool
		debugDir  string
		sources   []string
		limit     int
	)

	cmd := &cobra.Command{
		Use:   "setup [<runner>]",
		Short: "Create and tailor this repository's trail runners",
		Long: `Set up the .entire/runners/*.json evaluators for this repository.

Runners (risk, confidence, drift, security, review, …) score and review a
branch's changes. The shipped templates are generic; "setup" tailors them to
THIS repo using gathered signal — its docs and structure, merged PRs and
issues, checkpoint churn hotspots, and past trail findings.

- In a repo with no runners, setup creates the default set first (use --yes to
  skip the confirmation), then tailors them.
- Run again in a repo that already has runners and setup offers to re-tune them.

By default setup prints the tailoring prompt to stdout, ready to paste into
your agent. With --run it executes the prompt headlessly through your
configured summary provider and rewrites the runner files in place (review with
git diff).

If <runner> is given (e.g. "risk" or "trail-risk"), only that runner is tuned.`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			runner := ""
			if len(args) == 1 {
				runner = args[0]
			}
			return runRunnerSetup(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), runnerSetupOptions{
				runner:       runner,
				run:          run,
				assumeYes:    assumeYes,
				debugDir:     debugDir,
				sources:      sources,
				limit:        limit,
				insecureHTTP: runnerInsecureHTTP(cmd),
			})
		},
	}

	cmd.Flags().BoolVar(&run, "run", false,
		"Run the configured summary provider headlessly to rewrite the runner files in place (default: print the prompt)")
	cmd.Flags().StringSliceVar(&sources, "sources", nil,
		"Comma-separated data sources to gather: repo, prs, checkpoints, trails, all (default: all)")
	cmd.Flags().IntVar(&limit, "limit", 20, "How many recent PRs/issues/trails to sample")
